1	export type QueueState = "idle" | "running" | "succeeded" | "failed" | "paused";
2	export function stateAfter(result: "started" | "ok" | "error" | "pause"): QueueState {
3	  return { started: "running", ok: "succeeded", error: "failed", pause: "paused" }[result] as QueueState;
4	}
5

1	import type { QueueState } from "./queue";
2	export const statusVisuals = {
3	  idle: { label: "Start", path: "assets/start.svg", frames: 1 },
4	  running: { label: "Working", path: "assets/working.png", frames: 4 },
5	  paused: { label: "Paused", path: "assets/paused.png", frames: 1 },
6	  succeeded: { label: "Ready", path: "assets/ready-confirmed.png", frames: 1 },
7	  failed: { label: "Retry", path: "assets/error-retry.png", frames: 1 },
8	};
9	export const display = { cell: [16, 16], scale: 3, filter: "nearest", frameMs: 100, background: "#172336" };
10	export function statusCell(state: QueueState) { return statusVisuals[state]; }
11	export function compactStatus(state: QueueState) { return statusVisuals[state]; }
12	export function accountBadge(registry: Record<string, string>, account: string) {
13	  return registry[account]; // Provided by the service; not enumerable in this checkout.
14	}
15

1	// Execute the actual source consumers; this is not a renderer.
2	import assert from 'node:assert/strict';
3	import { readFileSync } from 'node:fs';
4	import { createHash } from 'node:crypto';
5	import { stateAfter } from './src/queue.ts';
6	import { statusCell, compactStatus, display } from './src/queue-view.ts';
7	const expected = process.argv[2];
8	assert.ok(expected, 'Pass the selected PLAR delivery path');
9	const state = stateAfter('ok');
10	assert.equal(state, 'succeeded');
11	const consumers = [statusCell(state), compactStatus(state)];
12	for (const consumer of consumers) {
13	  assert.equal(consumer.path, expected);
14	  assert.equal(consumer.frames, 1);
15	}
16	const data = readFileSync(new URL(expected, import.meta.url));
17	assert.equal(data.subarray(0,8).toString('hex'), '89504e470d0a1a0a');
18	assert.deepEqual([data.readUInt32BE(16), data.readUInt32BE(20)], display.cell);
19	assert.equal(display.filter, 'nearest');
20	const hash = bytes => createHash('sha256').update(bytes).digest('hex');
21	console.log(JSON.stringify({state, consumers, display, file: expected,
22	  sha256: hash(data), sources: Object.fromEntries(['src/queue.ts','src/queue-view.ts'].map(
23	    p => [p, hash(readFileSync(new URL(p, import.meta.url)))])),
24	  scope: 'Executed backend-to-view mapping and actual file/header lookup; no renderer, alpha compositing or artistic acceptance.'}, null, 2));
